TARGET_ANSWERS = 'ABCDBCDACB'
def make(i, row):
    tag, prompt, opts, answer, reason = row
    target = TARGET_ANSWERS[i - 1]
    position = ord(target) - 65
    distractors = [t for t in opts if t != answer]
    arranged = distractors[:position] + [answer] + distractors[position:]
    options = [{'id': chr(65+j), 'text': t} for j, t in enumerate(arranged)]
    aid = target
    steps = [f'讀題定位：圈出「{tag}」以及半球、低壓／高壓、等壓線或時間序列。', f'建立判準：{reason}', f'核對答案：選項 {aid}「{answer}」符合地轉偏向與氣壓系統判讀。', '排除誘答：分清壓力梯度、偏向作用、摩擦與觀測證據，不能把單一箭頭當成完整風場。', '最後回查：確認方向是相對運動或中心的位置描述，且推論沒有超出資料。']
    return {'id': f'question-science-content-ib-iv-3-{i}', 'subject': 'science', 'type': 'single-choice', 'prompt': prompt, 'options': options, 'knowledgeIds': ['kg-science-content-ib-iv-3'], 'difficulty': 'medium', 'answer': {'value': aid, 'explanation': reason}, 'provenance': {'origin': 'original', 'license': 'All rights reserved', 'sourceUrl': URL, 'sourceLocator': '公立國中段考自然科；研究地轉偏向、高低氣壓旋轉、等壓線與天氣圖判讀的能力方向。', 'authoringNote': '依官方課綱 KG 與公立國中公開試題能力方向獨立改寫，未複製原文、選項、圖表或答案；待第二輪 AI／Terra 內容複核。'}, 'reviewStatus': 'draft', 'updatedAt': '2026-09-08', 'lessonId': 'lesson-science-content-ib-iv-3', 'examPatternRefs': [{'url': URL, 'title': '公立國中段考自然科；僅研究題型與能力方向，未複製原題。', 'year': '114', 'subject': 'science', 'locator': '地球自轉與高低氣壓旋轉', 'observedPattern': '能力方向研究後原創改寫', 'reuseDecision': 'pattern-only', 'status': 'recorded', 'locatorLevel': 'paper'}], 'solutionStrategy': '先確認半球與壓力系統，再用壓力梯度、地轉偏向及摩擦判斷風場，最後回到天氣圖的多點與時間序列證據。', 'solutionSteps': steps}
